<template>
<div class="pg"><div class="hd"><h2>📝 NLP自然语言处理</h2><el-button type="primary" @click="showTrain=true">+ 新建NLP任务</el-button></div>
<el-row :gutter="16" class="st"><el-col :span="6"><el-card><el-statistic title="总任务" :value="jobs.length"/></el-card></el-col><el-col :span="6"><el-card><el-statistic title="完成" :value="jobs.filter(j=>j.status==='completed').length"/></el-card></el-col><el-col :span="6"><el-card><el-statistic title="进行中" :value="jobs.filter(j=>j.status==='training').length"/></el-card></el-col></el-row>
<el-card><template #header><span>训练任务</span><el-button size="small" style="float:right" @click="refreshJobs">刷新</el-button></template>
<el-table :data="jobs" stripe v-loading="loading"><el-table-column prop="job_id" label="ID" width="80"/><el-table-column label="任务" width="110"><template #default="{row}">{{row.config?.task_type||'分类'}}</template></el-table-column><el-table-column label="模型" width="140"><template #default="{row}"><el-tag type="success" size="small">{{row.config?.model||'BERT'}}</el-tag></template></el-table-column><el-table-column label="进度" width="180"><template #default="{row}"><el-progress :percentage="row.progress||0" :status="row.status==='completed'?'success':''"/></template></el-table-column><el-table-column label="指标" width="120"><template #default="{row}"><span v-if="row.metrics">Acc:{{(row.metrics.accuracy*100).toFixed(1)}}%</span></template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='completed'?'success':row.status==='failed'?'danger':'warning'" size="small">{{row.status}}</el-tag></template></el-table-column><el-table-column label="创建时间" width="170"><template #default="{row}">{{row.created_at?.slice(0,19)}}</template></el-table-column></el-table></el-card>
<el-dialog v-model="showTrain" title="NLP训练" width="500px"><el-form :model="f" label-width="90px"><el-form-item label="任务类型"><el-radio-group v-model="f.task_type"><el-radio label="classification">文本分类</el-radio><el-radio label="ner">命名实体识别</el-radio><el-radio label="sentiment">情感分析</el-radio></el-radio-group></el-form-item><el-form-item label="模型"><el-select v-model="f.model" style="width:100%"><el-option label="BERT-base" value="bert-base"/><el-option label="RoBERTa" value="roberta-base"/><el-option label="DistilBERT" value="distilbert-base"/></el-select></el-form-item><el-form-item label="数据集"><el-select v-model="f.dataset" style="width:100%"><el-option label="IMDB(英文影评)" value="imdb"/><el-option label="ChnSentiCorp(中文)" value="chnsenticorp"/></el-select></el-form-item><el-form-item label="Epochs"><el-input-number v-model="f.epochs" :min="1" :max="20"/></el-form-item></el-form><template #footer><el-button @click="showTrain=false">取消</el-button><el-button type="primary" @click="doTrain" :loading="tl">训练</el-button></template></el-dialog>
</div></template>
<script setup lang="ts">import {ref,onMounted} from 'vue';import {ElMessage} from 'element-plus';import {get,post} from '@/api/legacy';
const loading=ref(false),tl=ref(false),showTrain=ref(false),jobs=ref<any[]>([]),f=ref({task_type:'classification',model:'bert-base',dataset:'imdb',epochs:3,batch_size:16});
onMounted(refreshJobs);async function refreshJobs(){loading.value=true;try{const r=await get('/nlp/jobs');jobs.value=r.jobs||[]}catch{}finally{loading.value=false}}
async function doTrain(){tl.value=true;try{await post('/nlp/train',f.value);ElMessage.success('NLP训练启动');showTrain.value=false;refreshJobs()}catch(e:any){ElMessage.error('失败')}finally{tl.value=false}}</script>
<style scoped>.pg{padding:24px}.hd{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.hd h2{margin:0;font-size:20px}.st{margin-bottom:20px}</style>
